fn count_uppercase(text: &Vec<char>) -> u64 {
    // Base case: if the input vector is empty, return 0
    if text.is_empty() {
        return 0;
    }
    
    // Recursive case: check the first character and count it if it's uppercase
    let first_char = text[0];
    let count = if first_char.is_ascii_uppercase() {
        1
    } else {
        0
    };
    
    // Recursively call count_uppercase on the rest of the vector
    count + count_uppercase(&text[1..].to_vec())
}

fn main() {
    let chars = vec!['A', 'b', 'C', '1', 'D', '!', 'E'];
    let result = count_uppercase(&chars);
    println!("Number of uppercase letters: {}", result); // Output: 4
}